B.boL=new A.ko(B.aAv,null)
B.bsd=new A.xE("3.4 Dados de localizacao",null)
B.ayj=s(["Localizacao aproximada e precisa para mapas e cobertura","Rastreamento do pedido e do estafeta","Calculo de rotas e tempos estimados"],t.s)
B.boD=new A.ko(B.ayj,null)
B.bs8=new A.xE("3.5 Comunicacoes e dados tecnicos",null)
